#!/usr/bin/env python3
"""
Round 200o (culprits), 14 October 2026. Needs round 199o.

Shorter titles; population and country rows take part in the combine; faster reads.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 200o (14 October)\n\nNeeds round 199o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Titles (asked 14 October): 260 rows over 70 characters get shorter titles\n  (SHORT_NAMES, applied at load), each still saying what sets it apart and\n  its source in brackets; the full title is kept (cfg.fullName) and opens the\n  row\'s i note ("Full title: ..."). Catalogue titles (GFW_TITLES) not yet done.\n- Combine: rows drawn as relief (population density, livestock, NO2) took no\n  part (rowRasterSource leaves relief sources out): they are now read from\n  their coloured picture (<id>-col). Country-shading rows on the shared\n  boundaries source were left out too: they now take part through the\n  countries they have a figure for (cfg._countryTotals), shown whole.\n- Combine speed: every row\'s file, picture and whole-archive read starts at\n  once, so waits overlap; one archive read per row is shared (COMBO.worldP);\n  12 squares read at a time (was 6). The run\'s time is said at the end of\n  the message, to find what is slow next.\n- The groups list ("Which layers count together") moved under the combine\'s\n  title, above "Choose a way here".\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round200o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 199o" not in h.read_text(encoding="utf-8"):
        sys.exit("round200o: round 199o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round200o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/test.mjs", check=False)
            sys.exit("round200o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round200o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
